const studentPrompts=[{"en":"Which words make the two registers different?","ko":"두 말투의 차이를 만드는 단어는 무엇인가?"},{"en":"What kind of evidence does each document provide?","ko":"각 문서는 어떤 종류의 근거를 제공하는가?"},{"en":"Which terms concern action, and which concern an audience?","ko":"어떤 용어는 행위를, 어떤 용어는 관객을 가리키는가?"},{"en":"How does the comparison set frame Lear?","ko":"비교 집합은 리어를 어떻게 규정하는가?"},{"en":"What does each representation keep?","ko":"각 표현 방식에는 무엇이 남는가?"},{"en":"Does the label describe the work or this speech?","ko":"레이블은 작품을 설명하는가,이 대사를 설명하는가?"},{"en":"What does the conditional threat make death mean?","ko":"조건부 위협은 죽음을 어떤 의미로 만드는가?"},{"en":"How does the body change the meaning of death?","ko":"신체의 상황은 죽음의 의미를 어떻게 바꾸는가?"},{"en":"What cannot be recovered from this table?","ko":"이 표에서 복원할 수 없는 것은 무엇인가?"},{"en":"Does a word stand out more when few documents use it?","ko":"적은 문서에서 쓰이는 단어가 더 두드러지는가?"},{"en":"What changes when all three methods see the same word clues?","ko":"세 방법이 같은 단어 단서를 볼 때 무엇이 달라지는가?"},{"en":"Who acts on whom—and where is that relation lost?","ko":"누가 누구에게 행위하며,그 관계는 어디서 사라지는가?"},{"en":"Can one of these numbers tell us grief on its own?","ko":"이 숫자 하나만으로 슬픔을 알 수 있는가?"},{"en":"What relation surrounds each death-related expression?","ko":"죽음 관련 표현은 각각 어떤 관계 속에 놓이는가?"},{"en":"What might a flat picture leave out?","ko":"평면의 그림에서 무엇이 빠질 수 있는가?"},{"en":"Which choice gives the longer scene more influence?","ko":"어느 선택이 긴 장면에 더 큰 비중을 주는가?"},{"en":"Which panel describes a word, and which sets a task for learning?","ko":"어느 쪽이 단어를 표현하고, 어느 쪽이 학습할 과제를 제시하는가?"},{"en":"What word does the source supply?","ko":"원문이 제공하는 단어는 무엇인가?"},{"en":"Which completions are plausible before revealing the targets?","ko":"정답을 보기 전에 어떤 완성이 그럴듯한가?"},{"en":"When does the model change, rather than only make a guess?","ko":"모델이 추측만 하는 것이 아니라 바뀌는 때는 언제인가?"},{"en":"Which words resist a simple public/private division?","ko":"공적/사적구분에 쉽게 들어맞지 않는 단어는 무엇인가?"},{"en":"Who chooses the genre the model is taught to predict?","ko":"모델이 예측하도록 배우는 장르는 누가 정하는가?"},{"en":"Where do death and extremity sit before and after fine tuning?","ko":"미세 조정 전후 death와 extremity는 어디에 놓이는가?"},{"en":"When is the model checked against the genre assigned to the work?","ko":"작품에 부여한 장르와 모델을 비교하는 때는 언제인가?"},{"en":"What could a boundary position mean besides error?","ko":"경계의 위치는 오류 이외에 무엇을 의미할 수 있는가?"},{"en":"Where does this query place its strongest weights?","ko":"이 질의는 어느 위치에 가장 큰 가중치를 두는가?"},{"en":"Whose authority does his name?","ko":"his는 누구의 권위를 가리키는가?"},{"en":"What changes when death is a sanction or a bodily comparison?","ko":"죽음이 처벌일 때와 신체의 비교일 때 무엇이 달라지는가?"},{"en":"Are the named lenses fixed jobs of actual heads?","ko":"이름 붙인 렌즈는 실제 헤드의 고정된 역할인가?"},{"en":"Which picture combines word information, and which combines decisions about passages?","ko":"어느 그림이 단어 정보를 모으고, 어느 그림이 구절에 대한 판단을 모으는가?"},{"en":"Which claim is measured, and which is interpretive?","ko":"어느 주장이 측정이며,어느 주장이 해석인가?"},{"en":"Can a two-label model predict Romance?","ko":"두 레이블 모델이 로맨스를 예측할 수 있는가?"},{"en":"Which earlier decision can change the final prediction?","ko":"어떤 앞선 결정이 최종 예측을 바꿀 수 있는가?"},{"en":"Can this result be traced back to a source speech?","ko":"이 결과에서 원문 발화로 되돌아갈 수 있는가?"},{"en":"Which tags contribute text to the model input?","ko":"어떤 태그의 텍스트가 모델 입력에 들어가는가?"},{"en":"Could a spelling change alter tokenization?","ko":"철자 변화가 토큰화를 바꿀 수 있는가?"},{"en":"Who does I refer to before and after the boundary?","ko":"경계 전후 I는 각각 누구를 가리키는가?"},{"en":"What is removed besides a work-identification cue?","ko":"작품 식별 단서 이외에 무엇이 사라지는가?"},{"en":"How many model positions does each word occupy?","ko":"각 단어가 모델 위치를 몇 개 차지하는가?"},{"en":"What happens if the label dictionary is reversed?","ko":"레이블 사전을 뒤집으면 어떤 일이 생기는가?"},{"en":"Does this code check where a scene ends?","ko":"이 코드는 장면이 끝나는 곳을 확인하는가?"},{"en":"How many new works does the validation set introduce?","ko":"검증 집합에는 새 작품이 몇 개 들어오는가?"},{"en":"What is lost when we keep the same number of passages in each group?","ko":"각 무리에 같은 수의 구절을 남기면 무엇이 사라지는가?"},{"en":"Are the evaluation works already present in training?","ko":"평가 작품이 이미 학습에 포함되어 있는가?"},{"en":"Which values are known from the reference snippet alone?","ko":"기준 코드만으로 알 수 있는 수치는 무엇인가?"},{"en":"How often is the model adjusted during one pass through all the training passages?","ko":"모든 학습 구절을 한 번 읽는 동안 모델은 몇 번 조정되는가?"},{"en":"Are these curves from the same run and recording interval?","ko":"곡선들이 같은 실행과 기록 간격에서 나왔는가?"},{"en":"At what point do the two curves separate?","ko":"어느 지점에서 두 곡선이 갈라지는가?"},{"en":"What is being counted here?","ko":"여기에서는 무엇을 세는가?"},{"en":"Which mistake is actual Tragedy predicted as History?","ko":"실제 비극을 역사극으로 예측한 오류는 어느 칸인가?"},{"en":"Are these scores answering the same question?","ko":"이 점수들은 같은 질문에 답하는가?"},{"en":"Which number describes a whole passage, and which describes a link or a word?","ko":"어느 숫자는 구절 전체를, 어느 숫자는 연결이나 단어를 설명하는가?"},{"en":"Who claims authority, and who renews it?","ko":"누가 권위를 주장하고 누가 다시 부여하는가?"},{"en":"Which word has the largest reference contribution?","ko":"기준 설명에서 기여도가 가장 큰 단어는 무엇인가?"},{"en":"Do the two occurrences of I belong to one speaker?","ko":"두 I는 같은 화자의 말인가?"},{"en":"How do time and music extend the prison meditation?","ko":"시간과 음악은 감옥의 사색을 어떻게 확장하는가?"},{"en":"What differs between the two recorded decisions?","ko":"기록된 두 판단은 어떻게 다른가?"},{"en":"Which fields let another reader verify the input?","ko":"어떤 필드가 다른 독자의 입력 검증을 가능하게 하는가?"},{"en":"Who is exempted by unless it be the King?","ko":"왕이 아니라면이라는 조건은 누구를 예외로 두는가?"},{"en":"Does moving the threshold change the model score?","ko":"기준을 움직이면 모델 점수가 달라지는가?"},{"en":"Which local differences does the majority conceal?","ko":"다수결은 어떤 국소적 차이를 가리는가?"},{"en":"Can all four observations be true at once?","ko":"네 관찰이 동시에 참일 수 있는가?"},{"en":"Which line is an interpretation rather than a result reported by the model?","ko":"어느 행이 모델이 보고한 결과가 아니라 해석인가?"},{"en":"How do similar ranked words perform different functions?","ko":"비슷한 상위 단어는 어떻게 다른 기능을 하는가?"},{"en":"What are we asking the model to distinguish now?","ko":"이제 모델에게 무엇을 구별하라고 하는가?"},{"en":"What does counting labels lose about the strength of each score?","ko":"레이블만 세면 각 점수의 강도에 대해 무엇이 사라지는가?"},{"en":"What research question does each scheme create?","ko":"각 설계는 어떤 연구 질문을 만드는가?"},{"en":"Which counterexample would weaken your final claim?","ko":"어떤 반례가 최종 주장을 약화하는가?"}];
